mapper.select:
SELECT region_id AS regionId, region_code AS regionCode, sido_name AS sidoName, sigungu_name AS sigunguName, dong_name AS dongName, center_lat AS centerLat, center_lng AS centerLng, public_display_name AS publicDisplayName FROM region WHERE active_yn = 'Y'
AND CONCAT_WS(' ', sido_name, sigungu_name, dong_name, public_display_name) LIKE CONCAT('%', #{keyword}, '%')
ORDER BY sido_name, sigungu_name, dong_name LIMIT #{limit}
